def icon(name, extra=""):
    vb, d = ICONS[name]
    cls = ("icon " + extra).strip()
    return f'<svg class="{cls}" viewBox="{vb}" aria-hidden="true"><path d="{d}"/></svg>'

def sprite(names):
    """One hidden <svg> that defines each icon once, as <symbol id="i-NAME">."""
    syms = ''.join(
        f'<symbol id="i-{n}" viewBox="{ICONS[n][0]}"><path d="{ICONS[n][1]}"/></symbol>'
        for n in names)
    return f'<svg xmlns="http://www.w3.org/2000/svg" style="display:none">{syms}</svg>'


def use(name, extra=""):
    """A reference to an icon defined by sprite() in the same page."""
    cls = ("icon " + extra).strip()
    return f'<svg class="{cls}" aria-hidden="true"><use href="#i-{name}"/></svg>'
